void dijkstra(Graph *graph, int source) {
  int dist[MAX_NODES];
  bool settled[MAX_NODES] = {false};

  for (int v = 0; v < graph->count; v++) {
    dist[v] = INF;
  }
  dist[source] = 0;

  while (hasUnsettledVertex(graph, settled)) {
    int u = extractMin(dist, settled);
    settled[u] = true;

    forEach (Edge edge in graph->adj[u]) {
      int candidate = dist[u] + edge.weight;
      if (!settled[edge.to] && candidate < dist[edge.to]) {
        dist[edge.to] = candidate;
      }
    }
  }
}
